import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"9、【小畜】 乾下巽上","description":"周易尚氏学 - 9、【小畜】 乾下巽上","frontmatter":{"title":"9、【小畜】 乾下巽上","description":"周易尚氏学 - 9、【小畜】 乾下巽上"},"headers":[],"relativePath":"zh/classics/shangshi/014.md","filePath":"zh/classics/shangshi/014.md"}'),s={name:"zh/classics/shangshi/014.md"};function h(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_9、【小畜】-乾下巽上" tabindex="-1">9、【小畜】 乾下巽上 <a class="header-anchor" href="#_9、【小畜】-乾下巽上" aria-label="Permalink to “9、【小畜】 乾下巽上”">​</a></h1><p>卦上下皆阳。一阴止于内。故曰小畜。畜止也。太玄拟之曰敛。云阳气大满于外。微阴小敛于内。是其义也。旁通豫坤为云。上下皆坤爻。故曰密云。兑为雨。乃兑雨前遇巽风。为风吹散。云过日出。故不雨也。兑为西。伏坤为我。乾为郊。故曰自我西郊。言密云起自西郊。过而不留也。旧解多从虞翻。以半坎为云。既曰半坎。于密义似不合也。人知坎为云。不知坤亦为云。易林困之泰云。阴云四方。日在中央。以泰上坤为云也。人知坎为雨。不知兑亦为雨。上系云。润之以风雨。风谓巽。雨谓兑也。睽上九往遇雨。亦以兑为雨。</p><p>彖曰。小畜。柔得位。而上下应之。曰小畜。健而巽。刚中而志行。乃亨。密云不雨。尚往也。自我西郊。施未行也。</p><p>云下降方为雨。尚往者。言云气为风所吹。散而往上。故不能雨。又离火上炎。将密云冲散。不能下落为雨。故膏泽未施也。上往纯对下施言。</p><p>象曰。风行天上。小畜。君子以懿文德。</p><p>懿，美也。乾为德。离明。故曰文德。离明照天下。巽风散布四方。故曰懿文德。</p><p>初九。复自道。何其咎。吉。</p><p>复来也。初为阳本位。阳来初。故曰复。来初当位。故曰复自道。乾为道也。初前临重阳。行难。宜有咎。然当位有应。遁世无闷。故无咎也。</p><h3 id="象曰。复自道。其义吉也。" tabindex="-1">象曰。复自道。其义吉也。 <a class="header-anchor" href="#象曰。复自道。其义吉也。" aria-label="Permalink to “象曰。复自道。其义吉也。”">​</a></h3><p>义者宜也。言行谊如此。宜其吉也。</p><p>九二。牵复吉。</p><p>复来也。伏艮手。故曰牵复。玉篇云。牵速也。礼学记君子之教喻也。道而不牵。姤九三象云。其行次且。行未牵也。皆训奉为速。牵复者。速来也。言来居二得中也。若作阳复解。则九二失位。何复之有。又按九二失位无应。承乘皆阳。本不吉。兹曰吉者。徒以得中也。</p><h3 id="象曰。牵复在中。亦不自失也。" tabindex="-1">象曰。牵复在中。亦不自失也。 <a class="header-anchor" href="#象曰。牵复在中。亦不自失也。" aria-label="Permalink to “象曰。牵复在中。亦不自失也。”">​</a></h3><p>二虽不当位而在中。故吉。清儒多从虞翻。以五牵二。令二变阴应五为说。若然。则各卦非先变既济。不能说也。惑乱后学。莫此为甚。失佚古通。速复故曰不自佚。言不自安逸也。</p><p>九三。舆说輹。夫妻反目。</p><p>輹正义作辐。而马融以为车下缚。郑玄训为伏兔。则皆作輹。兹从马郑。伏坤为舆。伏震为輹。輹者舆所恃以行。乃舆在内而輹在外。则舆脱輹矣。乾为夫。坤为妻。巽得坤之初爻。故亦为妻。巽为白眼。卦二至上。正反巽。白眼与白眼相反。是反目也。三上无应。下乘重阳。故有是象。震輹象失传。左传僖十五年。筮遇归妹之睽。曰车脱其輹。夫归妹之睽。即震变离。震变离则震象毁。故曰车脱其輹。輹伏兔。上承车箱。下轭车轴。子夏传释名。皆以輹为车屐。因在箱下。有若履然。故左传以震为輹。屐。震象也。虞氏改作腹。非也。</p><h3 id="象曰。夫妻反目。不能正室也。" tabindex="-1">象曰。夫妻反目。不能正室也。 <a class="header-anchor" href="#象曰。夫妻反目。不能正室也。" aria-label="Permalink to “象曰。夫妻反目。不能正室也。”">​</a></h3><p>坎为室。坎伏不见。故曰不能正室。言夫无如妻何也。</p><p>六四。有孚。血去惕出。无咎。</p><p>四卦主。五阳孚之。故曰有孚。释文血马云当作恤。忧也。是马以血为恤之省文。而荀爽王弼等。直读为血。非也。坎为恤为惕。乃坎伏不见。故曰恤去惕出。言不忧惧也。四当位有应。上承重阳。故无咎。</p><h3 id="象日。有孚惕出。上合志也。" tabindex="-1">象日。有孚惕出。上合志也。 <a class="header-anchor" href="#象日。有孚惕出。上合志也。" aria-label="Permalink to “象日。有孚惕出。上合志也。”">​</a></h3><p>上谓五上。五上皆阳。四承之。阴遇阳得类。故曰合志。此与升初六之上合志义同也。巽为志。易林姤之小过。心志不亲。小过中爻正反巽。故心志不亲。又蒙之升。成子得志。亦以升下巽为志。盖心志在内。而巽为伏。故巽为志。</p><p>九五。有孚挛如。富以其邻。</p><p>孚谓孚于四。四卦主。阳喜阴。故下三阳亦孚于四。挛引也。牵也。言阳皆孚四。有若牵引连接也。九家谓五孚下三爻。虞翻强命二变谓五孚二。并非。阳于阳不孚也。五天子位。巽为利。五乘之。故富。伏震为邻。富以其邻。言五之所以富。以邻于四也。九家谓五以四阴作财。与下三阳共之。故曰不独富。深得经旨。</p><h3 id="象曰。有孚挛如。不独富也。" tabindex="-1">象曰。有孚挛如。不独富也。 <a class="header-anchor" href="#象曰。有孚挛如。不独富也。" aria-label="Permalink to “象曰。有孚挛如。不独富也。”">​</a></h3><p>不独义见前。</p><p>上九。既雨既处。尚德载。妇贞厉。月几望。君子征凶。</p><p>云上往。至上九而极。兑为雨。兑覆向下。是雨已下施也。故曰既雨。既已也。诗召南江有汜。其后也处。毛传。处止也。既处者。言雨已止也。德者雨泽也。尚德载。言雨泽下降。乾旋坤受。地得载其德泽也。巽为妇。柔之为道不利远。高处在上。非妇德所宜。故妇贞得此爻者。厉也。兑为月。互离为日。月西日东。相望。几。孟、荀作既。孟云。即望十六日也。纳甲法。十五日夜乾象。月盈甲。十六日平明巽象。月退辛。上九处巽之终。正既望也。既望则阳将消。又三无应。故征凶。自兑月象失传。小畜归妹中孚之月几望。旧解皆以坎为月。岂知易之言月。十九皆谓兑。说卦象。与经所用象。不尽同也。易林复之临云。月出平地。以临上坤为地。下兑为月也。又家人之小畜云。杲杲白日。为月所食。以小畜互离为日。兑为月。兑月侵入离体之半。故曰为月所食。兑月象。后惟邵子知之。而清易家皆不信。岂知邵子所用。与易林合。与易合哉。</p><h3 id="象曰。既雨既处。德积载也。君子征凶。有所疑也。" tabindex="-1">象曰。既雨既处。德积载也。君子征凶。有所疑也。 <a class="header-anchor" href="#象曰。既雨既处。德积载也。君子征凶。有所疑也。" aria-label="Permalink to “象曰。既雨既处。德积载也。君子征凶。有所疑也。”">​</a></h3><p>吴先生曰。古得德同字。德积载。即雨泽得为大地所载也。巽为疑。下无应。阳遇阳。故疑。</p><p>站长：孟、荀可能是指孟喜和荀爽，他们是西汉时期的易学家。应该当作「既望」，巽也为月始缺，如小畜「既雨既处...月既望」同理。</p>',31)])])}const f=e(s,[["render",h]]);export{_ as __pageData,f as default};
